dtsPropsFor.Button:
/** Only one `primary` per viewport — DESIGN.md states it as a rule, not a preference. Secondary actions are `secondary` (outlined) or `quiet`. `danger` is reserved for something that has broken or is about to be destroyed, never for ordinary emphasis. */
variant?: 'primary' | 'secondary' | 'quiet' | 'danger';
/** Renders `busyLabel` and disables the button. Separate from `disabled` on purpose: a busy button and an unavailable button mean different things to someone reading the screen. */
busy?: boolean;
/** Label shown while `busy` is true. */
busyLabel?: string;
fullWidth?: boolean;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
'aria-label'?: string;
className?: string;
style?: React.CSSProperties;
children: React.ReactNode;

dtsPropsFor.Field:
/** A real `<label>` bound by id — never a placeholder standing in for one. */
label: string;
/** Shown under the field, wired through `aria-describedby`, and marks the input `aria-invalid`. */
error?: string;
/** Helper text under the field, also announced via `aria-describedby`. */
hint?: string;
name?: string;
type?: string;
value?: string;
defaultValue?: string;
placeholder?: string;
required?: boolean;
disabled?: boolean;
autoComplete?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
className?: string;
style?: React.CSSProperties;

dtsPropsFor.Alert:
/** `error` means something has broken. It is NOT for "time is running out" or "you have not written enough yet" — DESIGN.md law L1 reserves red for failure. Use `warning` for informational urgency. `error` and `warning` announce assertively via role="alert"; `info` and `success` use role="status". */
tone: 'info' | 'success' | 'warning' | 'error';
/** Optional bold first line above the body. */
title?: string;
children: React.ReactNode;

dtsPropsFor.Card:
/** Renders the recessed layer (`--sunk` background, `--line-2` border, `--r-md` radius) instead of the raised one. Depth in this system comes from three background layers plus a hairline border — there is no shadow token and none should be added. */
sunk?: boolean;
style?: React.CSSProperties;
children: React.ReactNode;

dtsPropsFor.PageHeader:
/** Rendered as the page `<h1>`. */
title: string;
/** Muted line under the title. */
subtitle?: string;

dtsPropsFor.EmptyState:
title: string;
/** Say why it is empty. An empty state that offers a dead button is worse than one that admits the feature is not built. */
description: string;
/** Optional call to action — typically a `<Button>`. */
action?: React.ReactNode;

dtsPropsFor.ErrorState:
title: string;
description: string;
/** Optional recovery action — typically a `<Button>`. Announced via role="alert". */
action?: React.ReactNode;
